package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

// decodeEnvelope asserts the body matches the documented error envelope
// exactly: {"error": {"status": <int>, "code": <string>, "message": <string>}}.
func decodeEnvelope(t *testing.T, rec *httptest.ResponseRecorder) (status int, code, message string) {
	t.Helper()
	var got struct {
		Error struct {
			Status  int    `json:"status"`
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("error body is not valid JSON: %v; body=%q", err, rec.Body.String())
	}
	if got.Error.Status == 0 && got.Error.Code == "" && got.Error.Message == "" {
		t.Fatalf("error envelope missing 'error' object; body=%q", rec.Body.String())
	}
	return got.Error.Status, got.Error.Code, got.Error.Message
}

func TestSessionPostMissingParamsReturnsJSONEnvelope(t *testing.T) {
	h := sessionHandler(NewStore(30 * time.Minute))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/session", nil))

	if rec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusBadRequest)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	status, code, msg := decodeEnvelope(t, rec)
	if status != http.StatusBadRequest || code != "INVALID_ARGUMENT" || msg == "" {
		t.Fatalf("envelope = status:%d code:%q msg:%q", status, code, msg)
	}
}

func TestSessionGetUnknownSessionReturnsJSONEnvelope(t *testing.T) {
	h := sessionHandler(NewStore(30 * time.Minute))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/session?id=nope", nil))

	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusNotFound)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	status, code, _ := decodeEnvelope(t, rec)
	if status != http.StatusNotFound || code != "SESSION_NOT_FOUND" {
		t.Fatalf("envelope = status:%d code:%q", status, code)
	}
}

func TestSessionUnsupportedMethodReturnsJSONEnvelope(t *testing.T) {
	h := sessionHandler(NewStore(30 * time.Minute))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodDelete, "/session?id=x&user=y", nil))

	if rec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusMethodNotAllowed)
	}
	status, code, _ := decodeEnvelope(t, rec)
	if status != http.StatusMethodNotAllowed || code != "METHOD_NOT_ALLOWED" {
		t.Fatalf("envelope = status:%d code:%q", status, code)
	}
}

func TestSessionPostValidSucceedsAndGETRoundTrips(t *testing.T) {
	store := NewStore(30 * time.Minute)
	h := sessionHandler(store)

	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/session?id=s1&user=alice", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("POST status = %d, want 200", rec.Code)
	}

	rec = httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/session?id=s1", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("GET status = %d, want 200; body=%q", rec.Code, rec.Body.String())
	}
	var session map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &session); err != nil {
		t.Fatalf("GET body not JSON: %v", err)
	}
}

func TestWriteErrorEmitsExactEnvelopeShape(t *testing.T) {
	rec := httptest.NewRecorder()
	writeError(rec, http.StatusForbidden, "TEST_CODE", "no access")

	if rec.Code != http.StatusForbidden {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusForbidden)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	var raw map[string]map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &raw); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	errObj, ok := raw["error"]
	if !ok {
		t.Fatalf("missing top-level 'error' key: %v", rec.Body.String())
	}
	if len(raw) != 1 || len(errObj) != 3 {
		t.Fatalf("envelope shape mismatch: %v", rec.Body.String())
	}
	if errObj["status"] != float64(http.StatusForbidden) || errObj["code"] != "TEST_CODE" || errObj["message"] != "no access" {
		t.Fatalf("envelope fields wrong: %v", errObj)
	}
}

